import math

def is_square(n):
    if n < 0:
        return False
    x = math.isqrt(n)
    return x * x == n

import math

def count_squares(a, b):
    if a > b:
        return 0
    lo = math.isqrt(a)
    if lo * lo < a:
        lo += 1
    hi = math.isqrt(b)
    return max(0, hi - lo + 1)

