def is_perfect(n):
    if n < 2:
        return False
    tong = 0
    for i in range(1, n):
        if n % i == 0:
            tong += i
    return tong == n

def is_perfect(n):
    if n < 2:
        return False
    tong = 1  # 1 luôn là ước
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            tong += i
            if i != n // i:
                tong += n // i
    return tong == n

def is_palindrome(n):
    s = str(n)
    return s == s[::-1]

