def la_palindrome(s, bo_qua_khoang_trang=True, khong_phan_biet_hoa_thuong=True):
    # Tiền xử lý
    if bo_qua_khoang_trang or khong_phan_biet_hoa_thuong:
        s_loc = ''
        for ch in s:
            if bo_qua_khoang_trang and not ch.isalpha() and not ch.isdigit():
                continue
            if khong_phan_biet_hoa_thuong:
                ch = ch.lower()
            s_loc += ch
        s = s_loc

    # Kiểm tra
    return s == s[::-1]

