def kiem_tra_palindrome(s):
    trai = 0
    phai = len(s) - 1

    while trai < phai:
        # Bỏ qua ký tự không phải chữ/số từ bên trái
        while trai < phai and not s[trai].isalnum():
            trai += 1
        # Bỏ qua ký tự không phải chữ/số từ bên phải
        while trai < phai and not s[phai].isalnum():
            phai -= 1
        # So sánh
        if s[trai].lower() != s[phai].lower():
            return False
        trai += 1
        phai -= 1

    return True

s = input()
if kiem_tra_palindrome(s):
    print("Yes")
else:
    print("No")

