def ma_hoa(van_ban, buoc_dich):
    ket_qua = ''
    for ch in van_ban:
        if 'a' <= ch <= 'z':
            # Chữ thường
            so = (ord(ch) - ord('a') + buoc_dich) % 26
            ket_qua += chr(ord('a') + so)
        elif 'A' <= ch <= 'Z':
            # Chữ hoa
            so = (ord(ch) - ord('A') + buoc_dich) % 26
            ket_qua += chr(ord('A') + so)
        else:
            # Giữ nguyên ký tự khác (space, dấu câu, số...)
            ket_qua += ch
    return ket_qua

def giai_ma(van_ban, buoc_dich):
    ket_qua = ''
    for ch in van_ban:
        if 'a' <= ch <= 'z':
            # Dịch lùi: +26 - buoc_dich để tránh số âm
            so = (ord(ch) - ord('a') - buoc_dich + 26) % 26
            ket_qua += chr(ord('a') + so)
        elif 'A' <= ch <= 'Z':
            so = (ord(ch) - ord('A') - buoc_dich + 26) % 26
            ket_qua += chr(ord('A') + so)
        else:
            ket_qua += ch
    return ket_qua

def rot13(van_ban):
    return ma_hoa(van_ban, 13)

# ROT13(ROT13(x)) = x
print(rot13("HELLO"))    # "URYYB"
print(rot13("URYYB"))    # "HELLO"

