def binary_search(a, x):
    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == x:
            return mid            # Trả về vị trí tìm thấy
        elif a[mid] < x:
            left = mid + 1        # Bỏ nửa trái
        else:
            right = mid - 1       # Bỏ nửa phải
    return -1                     # Không tìm thấy

