```python
# Đề: Cho mảng A có N phần tử (N <= 3000). Kiểm tra xem
# có thể chọn ra 3 phần tử tạo thành cấp số cộng (a, b, c với b - a = c - b) không?
# Brute force O(n^3): duyệt i < j < k, kiểm tra điều kiện.

def co_cap_so_cong_bruteforce(A):
    N = len(A)
    for i in range(N):
        for j in range(i + 1, N):
            for k in range(j + 1, N):
                if A[j] - A[i] == A[k] - A[j]:
                    return True, (A[i], A[j], A[k])
    return False, None

# Test
A1 = [1, 3, 5, 7, 9]        # Đây là cấp số cộng: 1,3,5 or 3,5,7 ...
A2 = [1, 2, 3, 5, 8, 13]    # 1,2,3 là cấp số cộng

print(co_cap_so_cong_bruteforce(A1))  # True, (1, 3, 5)
print(co_cap_so_cong_bruteforce(A2))  # True, (1, 2, 3)

# Với N=3000, O(n^3) = 27 tỷ -> KHÔNG được!
# Cần tối ưu: dùng set để đạt O(n^2)

def co_cap_so_cong_toi_uu(A):
    S = set(A)
    N = len(A)
    for i in range(N):
        for j in range(i + 1, N):
            # Nếu có phần tử thứ ba = A[j] + (A[j] - A[i])
            thu_ba = A[j] + (A[j] - A[i])
            if thu_ba in S:
                return True, (A[i], A[j], thu_ba)
    return False, None

print(co_cap_so_cong_toi_uu(A1))  # True, (1, 3, 5)
```

**Phân tích**: Với N=3000, O(n^3) = 27 tỷ (quá chậm). Nhưng O(n^2) = 9 triệu (rất nhanh). Đây là bài học: **brute force cần dùng giới hạn, nhưng có thể tối ưu nhẹ bằng cách dùng set**.

